def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = str(value).strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()
        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            value = f"{local}@{domain}"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""
        return value

    def normalize_phone(value):
        value = str(value)
        match = re.search(r"x|ext|#", value, flags=re.IGNORECASE)
        if match:
            value = value[:match.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = str(value).strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = str(value).strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = str(value).strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))
        if not email and not phone:
            continue

        updated = parse_updated(row["updated"])
        source = str(row.get("source", "")).strip().lower()
        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", str(row.get("tags", "")))
            if tag.strip()
        }
        opted_out = str(row.get("opted_out", "")).strip().lower() in {
            "y", "yes", "true", "1"
        }

        prepared.append({
            "index": index,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row.get("zip", "")),
            "source": source,
            "updated": updated,
            "tags": tags,
            "opted_out": opted_out,
        })

    # Union rows that match by email or by phone plus non-empty last name.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a, root_b = find(a), find(b)
        if root_a != root_b:
            parent[root_b] = root_a

    email_owner = {}
    phone_name_owner = {}
    for i, person in enumerate(prepared):
        email = person["email"]
        if email:
            if email in email_owner:
                union(i, email_owner[email])
            else:
                email_owner[email] = i

        last_name = person["last_name"].casefold()
        phone = person["phone"]
        if phone and last_name:
            key = (phone, last_name)
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, person in enumerate(prepared):
        groups.setdefault(find(i), []).append(person)

    def preferred_row(group, field):
        candidates = [p for p in group if p[field]]
        if not candidates:
            return None
        return min(
            candidates,
            key=lambda p: (
                p["source"] != "manual",
                -p["updated"].timestamp(),
                p["index"],
            ),
        )

    output = []
    for group in sorted(groups.values(), key=lambda g: min(p["index"] for p in g)):
        result = {}
        for field in ("first_name", "last_name", "zip", "email", "phone"):
            chosen = preferred_row(group, field)
            result[field] = chosen[field] if chosen else ""

        source_row = preferred_row(group, "source")
        result["source"] = source_row["source"] if source_row else ""
        result["tags"] = ";".join(sorted(set().union(*(p["tags"] for p in group))))
        result["opted_out"] = "Y" if any(p["opted_out"] for p in group) else "N"
        result["updated"] = max(p["updated"] for p in group).strftime("%Y-%m-%d")
        output.append(result)

    return output
